function normalizeCatalog(raw) {
	const value = objectValue(raw);
	const categories = Array.isArray(value.categories) ? value.categories : [];
	const products = Array.isArray(value.products) ? value.products : [];
	const normalizedCategories = categories
		.map((category) => objectValue(category))
		.map((category) => ({
			id: cleanString(category.id, ''),
			label: cleanString(category.label, ''),
			helper: cleanString(category.helper, ''),
			order: Number(category.order)
		}))
		.filter((category) => category.id && category.label)
		.sort((first, second) => {
			const firstOrder = Number.isFinite(first.order) ? first.order : 999;
			const secondOrder = Number.isFinite(second.order) ? second.order : 999;
			return firstOrder === secondOrder ? first.label.localeCompare(second.label) : firstOrder - secondOrder;
		});
	const categoryIds = new Set(normalizedCategories.map((category) => category.id));
	const normalizedProducts = products
		.map((product) => objectValue(product))
		.map((product) => ({
			id: cleanString(product.id, ''),
			skuid: cleanString(product.skuid, ''),
			name: cleanString(product.name, ''),
			category: cleanString(product.category, ''),
			price: Number(product.price),
			icon: cleanString(product.icon, ''),
			cid: cleanString(product.cid, ''),
			imageCid: cleanString(product.imageCid, ''),
			imageUrl: cleanString(product.imageUrl, ''),
			description: cleanString(product.description, ''),
			vendor: cleanString(product.vendor, ''),
			badge: cleanString(product.badge, ''),
			packLabel: cleanString(product.packLabel, ''),
			digital: product.digital === true,
			order: Number(product.order)
		}))
		.filter((product) =>
			product.id &&
			product.name &&
			product.category &&
			categoryIds.has(product.category) &&
			Number.isFinite(product.price) &&
			product.price >= 0
		)
		.sort((first, second) => {
			const firstOrder = Number.isFinite(first.order) ? first.order : 999;
			const secondOrder = Number.isFinite(second.order) ? second.order : 999;
			return firstOrder === secondOrder ? first.name.localeCompare(second.name) : firstOrder - secondOrder;
		});

	if (!normalizedCategories.length || !normalizedProducts.length) return null;
	return {
		categories: normalizedCategories,
		products: normalizedProducts
	};
}

function activeCatalog(raw) {
	return normalizeCatalog(raw) || defaultCatalog();
}

function activeProducts(catalog) {
	return activeCatalog(catalog).products;
}

function normalizeCategory(raw, catalog) {
	const fallback = 'all';
	const value = cleanString(raw, fallback).toLowerCase();
	const categories = activeCatalog(catalog).categories;
	return value === 'all' || categories.some((category) => category.id === value) ? value : fallback;
}

function normalizeProductId(raw, category, catalog) {
	const products = activeProducts(catalog);
	const fallbackProduct =
		(category === 'all' ? products[0] : products.find((product) => product.category === category)) ||
		products[0] ||
		null;
	const fallback = fallbackProduct ? fallbackProduct.id : '';
	const value = cleanString(raw, fallback);
	return products.some((product) => product.id === value) ? value : fallback;
}

function normalizeCart(raw, catalog) {
	const cart = {};
	const value = objectValue(raw);
	for (const product of activeCatalog(catalog).products) {
		const quantity = Number(value[product.id]);
		if (Number.isFinite(quantity) && quantity > 0) {
			cart[product.id] = Math.round(quantity);
		}
	}
	return cart;
}

function normalizeQuantities(raw, catalog) {
	const quantities = {};
	const value = objectValue(raw);
	for (const product of activeCatalog(catalog).products) {
		const quantity = Number(value[product.id]);
		quantities[product.id] = Number.isFinite(quantity) && quantity > 0 ? Math.max(1, Math.round(quantity)) : 1;
	}
	return quantities;
}

function normalizeTheme(raw) {
	const value = cleanString(raw, 'auto').toLowerCase();
	return ['auto', 'light', 'dark'].includes(value) ? value : 'auto';
}

function normalizeState(raw) {
	const fallback = defaultState();
	const value = objectValue(raw);
	const view = ['products', 'product', 'cart', 'checkout', 'orders', 'success', 'failed', 'contact'].includes(value.view)
		? value.view
		: fallback.view;
	const catalog = normalizeCatalog(value.catalog);
	const category = normalizeCategory(value.category, catalog);
	const savedDeliveries = normalizeSavedDeliveries(value.savedDeliveries, value.savedDelivery);
	const selectedDeliveryProfileId = savedDeliveries.some((profile) => deliveryProfileId(profile) === value.selectedDeliveryProfileId)
		? value.selectedDeliveryProfileId
		: '';
	return {
		...fallback,
		...value,
		view,
		category,
		selectedProductId: normalizeProductId(value.selectedProductId, category, catalog),
		coreId: typeof value.coreId === 'string' && value.coreId.trim() ? value.coreId.trim() : null,
		userEmail: cleanString(value.userEmail, fallback.userEmail),
		emailRequestStatus: ['idle', 'requested', 'resolved'].includes(value.emailRequestStatus)
			? value.emailRequestStatus
			: fallback.emailRequestStatus,
		countryCode: cleanString(value.countryCode, fallback.countryCode).toUpperCase(),
		theme: normalizeTheme(value.theme),
		lastAddedProductId: cleanString(value.lastAddedProductId, fallback.lastAddedProductId),
		query: typeof value.query === 'string' ? value.query : fallback.query,
		page: Number.isFinite(Number(value.page)) && Number(value.page) > 0 ? Math.floor(Number(value.page)) : fallback.page,
		productQuantities: normalizeQuantities(value.productQuantities, catalog),
		cart: normalizeCart(value.cart, catalog),
		delivery: normalizeDelivery(value.delivery),
		saveDelivery: value.saveDelivery !== false,
		savedDelivery: savedDeliveries[0] || null,
		savedDeliveries,
		selectedDeliveryProfileId,
		checkoutStatus: cleanString(value.checkoutStatus, fallback.checkoutStatus),
		lastOrder: value.lastOrder && typeof value.lastOrder === 'object' ? value.lastOrder : null,
		catalog,
		catalogStatus: ['idle', 'loading', 'loaded', 'error'].includes(value.catalogStatus)
			? value.catalogStatus
			: fallback.catalogStatus,
		catalogError: cleanString(value.catalogError, fallback.catalogError),
		catalogSource: cleanString(value.catalogSource, fallback.catalogSource),
		settings: normalizeSettings(value.settings),
		updatedAt: typeof value.updatedAt === 'string' ? value.updatedAt : null
	};
}

function getState(hostApi) {
	const storage = hostApi && hostApi.storage;
	const raw = storage && typeof storage.get === 'function' ? storage.get(STATE_KEY) : null;
	return normalizeState(raw);
}

function saveState(hostApi, next) {
	const storage = hostApi && hostApi.storage;
	if (storage && typeof storage.set === 'function') {
		storage.set(STATE_KEY, normalizeState(next));
	}
}

function stateAction(state, patch, message) {
	return {
		type: 'storage',
		key: STATE_KEY,
		value: normalizeState({
			...state,
			...patch
		}),
		message,
		level: message ? 'success' : undefined
	};
}


// src/catalog.ts
// @ts-nocheck
function catalogProducts(state) {
	return state && state.catalog && Array.isArray(state.catalog.products) && state.catalog.products.length
		? state.catalog.products
		: SHOP_PRODUCTS;
}

function catalogCategories(state) {
	return state && state.catalog && Array.isArray(state.catalog.categories) && state.catalog.categories.length
		? state.catalog.categories
		: SHOP_CATEGORIES;
}

function categoryById(id, state) {
	return catalogCategories(state).find((category) => category.id === id) || catalogCategories(state)[0];
}

function productCategory(product, state) {
	return categoryById(product.category, state);
}

function filteredProducts(state) {
	const query = state.query.trim().toLowerCase();
	return catalogProducts(state).filter((product) => {
		const category = productCategory(product, state);
		const categoryMatch = state.category === 'all' || product.category === state.category;
		const queryMatch = !query || [
			product.name,
			category.label,
			product.description
		].join(' ').toLowerCase().includes(query);
		return categoryMatch && queryMatch;
	});
}

function selectedProduct(state) {
	return (
		catalogProducts(state).find((product) => product.id === state.selectedProductId) ||
		filteredProducts(state)[0] ||
		catalogProducts(state)[0] ||
		null
	);
}

function productsByCategory(categoryId, state) {
	return catalogProducts(state).filter((product) => product.category === categoryId);
}

function categoryProductCount(categoryId, state) {
	return productsByCategory(categoryId, state).length;
}

function allCategories(state) {
	return [
		{ id: 'all', label: 'All', helper: 'Every listing', order: 0 },
		...catalogCategories(state)
	];
}

function catalogSettings(state) {
	const fallback = defaultState().settings;
	const settings = state && state.settings && typeof state.settings === 'object' ? state.settings : {};
	return normalizeSettings({
		...fallback,
		...settings
	});
}

function catalogProvider(state) {
	const settings = catalogSettings(state);
	const provider = settings.catalogProvider;
	if (provider === 'd1' && settings.catalogD1Url) return 'd1';
	if (provider === 'remote') return 'remote';
	const ref = settings.catalogRef.trim();
	if (provider !== 'local' && ref && !ref.startsWith('data/')) return 'remote';
	return 'local';
}

function catalogUrl(state) {
	const settings = catalogSettings(state);
	if (catalogProvider(state) === 'd1') return settings.catalogD1Url;
	const ref = settings.catalogRef.trim();
	if (!ref) return 'https://ipf.sk';
	if (/^https?:\/\//i.test(ref)) return ref;
	if (ref.startsWith('ipfs://')) {
		return `https://ipf.sk/ipfs/${ref.slice(7).replace(/^\/+/, '')}`;
	}
	if (ref.startsWith('ipns://')) {
		return `https://ipf.sk/ipns/${ref.slice(7).replace(/^\/+/, '')}`;
	}
	if (ref.startsWith('ipns/')) return `https://ipf.sk/${ref}`;
	if (ref.startsWith('ipfs/')) return `https://ipf.sk/${ref}`;
	return `https://ipf.sk/ipfs/${ref.replace(/^\/+/, '')}`;
}

function productUrl(state, product) {
	if (product.imageUrl && /^https?:\/\//i.test(product.imageUrl)) return product.imageUrl;
	const cid = product.imageCid || product.cid;
	if (!cid) return catalogUrl(state);
	return `https://ipf.sk/ipfs/${cid}`;
}

function productImageUrl(state, product) {
	return productUrl(state, product);
}

function usesRemoteCatalog(state) {
	return catalogProvider(state) !== 'local';
}

function sleep(ms) {
	return new Promise((resolve) => setTimeout(resolve, ms));
}

function normalizeRemoteCatalogPayload(payload) {
	const value = payload && typeof payload === 'object' && !Array.isArray(payload) ? payload : {};
	const categories = Array.isArray(value.categories) ? value.categories : [];
	const products = Array.isArray(value.products) ? value.products : Array.isArray(value.items) ? value.items : [];
	return normalizeCatalog({ categories, products });
}

async function loadCatalogJson(hostApi, state) {
	const url = catalogUrl(state);
	let lastError = 'Unable to load catalog.';
	for (let attempt = 0; attempt < 3; attempt += 1) {
		if (attempt > 0) await sleep(attempt * 1500);
		const response = await hostApi.network.getJson({
			url,
			timeoutMs: 12000
		}).catch((error) => {
			lastError = error && error.message ? error.message : 'Catalog request failed.';
			return null;
		});
		if (!response) continue;
		if (!response.ok) {
			lastError = `Catalog request failed (${response.status}).`;
			continue;
		}
		const catalog = normalizeRemoteCatalogPayload(response.body);
		if (catalog) return { catalog, source: url };
		lastError = 'Catalog JSON is missing valid categories or products.';
	}
	throw new Error(lastError);
}

function maybeLoadCatalog(hostApi, state) {
	if (!usesRemoteCatalog(state)) return;
	const source = catalogUrl(state);
	if (state.catalogStatus === 'loading') return;
	if (state.catalogStatus === 'loaded' && state.catalogSource === source && state.catalog) return;
	if (state.catalogStatus === 'error' && state.catalogSource === source) return;

	saveState(hostApi, {
		...state,
		catalogStatus: 'loading',
		catalogError: '',
		catalogSource: source
	});

	loadCatalogJson(hostApi, state)
		.then((result) => {
			const nextState = getState(hostApi);
			saveState(hostApi, {
				...nextState,
				catalog: result.catalog,
				catalogStatus: 'loaded',
				catalogError: '',
				catalogSource: result.source,
				category: 'all',
				selectedProductId: result.catalog.products[0] ? result.catalog.products[0].id : nextState.selectedProductId,
				page: 1
			});
		})
		.catch((error) => {
			const nextState = getState(hostApi);
			saveState(hostApi, {
				...nextState,
				catalog: null,
				catalogStatus: 'error',
				catalogError: error && error.message ? error.message : 'Unable to load catalog.',
				catalogSource: source
			});
		});
}


// src/cart.ts
// @ts-nocheck
function formatMoney(value, currency) {
	const amount = Number(value);
	const safe = Number.isFinite(amount) ? amount : 0;
	const code = currency || SHOP_CONFIG.defaultCurrency;
	try {
		return new Intl.NumberFormat('en-US', {
			style: 'currency',
			currency: code,
			maximumFractionDigits: safe % 1 === 0 ? 0 : 2
		}).format(safe);
	} catch {
		return `${safe.toFixed(2)} ${code}`;
	}
}

function cartItems(state) {
	return catalogProducts(state)
		.map((product) => ({
			product,
			quantity: state.cart[product.id] || 0
		}))
		.filter((item) => item.quantity > 0);
}

function cartCount(state) {
	return cartItems(state).reduce((sum, item) => sum + item.quantity, 0);
}

function cartSubtotal(state) {
	return cartItems(state).reduce((sum, item) => sum + item.product.price * item.quantity, 0);
}

function deliveryFeeAmount(state) {
	const fee = Number(SHOP_CONFIG.deliveryFee);
	if (!Number.isFinite(fee) || fee <= 0) return 0;
	const requiresDelivery = cartItems(state).some((item) => item.product.digital !== true);
	return requiresDelivery ? fee : 0;
}

function cartTotal(state) {
	return cartSubtotal(state) + deliveryFeeAmount(state);
}

function wholeQuantity(value) {
	const quantity = Number(value);
	return Number.isFinite(quantity) && quantity > 0 ? Math.max(1, Math.round(quantity)) : 1;
}

function productQuantity(state, productId) {
	return wholeQuantity(state.productQuantities && state.productQuantities[productId]);
}

function setProductQuantity(state, productId, quantity) {
	const product = catalogProducts(state).find((item) => item.id === productId);
	if (!product) return state;
	return normalizeState({
		...state,
		productQuantities: {
			...state.productQuantities,
			[productId]: wholeQuantity(quantity)
		}
	});
}

function incrementProductQuantity(state, productId) {
	return setProductQuantity(state, productId, productQuantity(state, productId) + 1);
}

function decrementProductQuantity(state, productId) {
	return setProductQuantity(state, productId, Math.max(1, productQuantity(state, productId) - 1));
}

function addQuantityToCart(state, productId, quantity) {
	const product = catalogProducts(state).find((item) => item.id === productId);
	if (!product) return state;
	const cart = { ...state.cart };
	const current = cart[productId] || 0;
	cart[productId] = current + wholeQuantity(quantity);
	return normalizeState({ ...state, cart, checkoutStatus: 'draft', lastAddedProductId: productId });
}

function addToCart(state, productId) {
	return addQuantityToCart(state, productId, 1);
}

function removeOneFromCart(state, productId) {
	const cart = { ...state.cart };
	const current = cart[productId] || 0;
	if (current <= 1) {
		delete cart[productId];
	} else {
		cart[productId] = current - 1;
	}
	return normalizeState({ ...state, cart, checkoutStatus: 'draft' });
}

function removeProductFromCart(state, productId) {
	const cart = { ...state.cart };
	delete cart[productId];
	return normalizeState({ ...state, cart, checkoutStatus: 'draft' });
}

function orderReference(state) {
	const ids = cartItems(state).map((item) => `${item.product.id}x${item.quantity}`).join('-');
	return `ipfs-shop-${ids || 'empty'}`;
}

function deliverySummary(delivery) {
	const country = countryNameFromCode(delivery.country) || delivery.country;
	const cityLine = [delivery.city, delivery.state, delivery.zip, country].filter(Boolean).join(', ');
	return [delivery.address, delivery.address2, cityLine].filter(Boolean).join(' • ') || 'Not entered';
}

function collectorAccount() {
	return SHOP_CONFIG.collectorAccount || SHOP_CONFIG.defaultMerchantAccount;
}


// src/ui/shared.ts
// @ts-nocheck
function shopLogoUrl() {
	const context = typeof pluginContext === 'object' && pluginContext ? pluginContext : null;
	if (SHOP_CONFIG.logoSrc && /^https?:\/\//i.test(SHOP_CONFIG.logoSrc)) return SHOP_CONFIG.logoSrc;
	if (SHOP_CONFIG.logoUrl && /^https?:\/\//i.test(SHOP_CONFIG.logoUrl)) return SHOP_CONFIG.logoUrl;
	return (SHOP_CONFIG.logoSrc || SHOP_CONFIG.logoUrl) && context && typeof context.iconUrl === 'string' ? context.iconUrl : '';
}

function shopLogoMarkup() {
	const logo = shopLogoUrl();
	return logo ? `<img class="wm-logo" src="${escapeHtml(logo)}" alt="" />` : '';
}

function escapeHtml(value) {
	return String(value ?? '')
		.replace(/&/g, '&amp;')
		.replace(/</g, '&lt;')
		.replace(/>/g, '&gt;')
		.replace(/"/g, '&quot;')
		.replace(/'/g, '&#39;');
}

function addFrameAction(actions, action) {
	const id = `action-${Object.keys(actions).length + 1}`;
	actions[id] = action;
	return id;
}

function actionAttr(actions, action) {
	return `data-plugin-action="${addFrameAction(actions, action)}"`;
}

function bankNavigateAction() {
	return { type: 'navigate', href: '/', target: '_self', sameWindow: true };
}

function frameButton(actions, label, action, variant = 'primary', extraClass = '') {
	return `<button type="button" class="wm-btn wm-btn-${variant} ${extraClass}" ${actionAttr(actions, action)}>${escapeHtml(label)}</button>`;
}

