// src/stock.ts
// @ts-nocheck
function stockItems(state) {
	return cartItems(state).map((item) => ({
		id: item.product.id,
		skuid: item.product.skuid || '',
		name: item.product.name,
		quantity: item.quantity
	}));
}

function stockPayload(state, type, result) {
	const reference = result && result.request && result.request.reference ? result.request.reference : orderReference(state);
	return {
		type,
		shop: {
			name: SHOP_CONFIG.name
		},
		payment: {
			reference,
			sessionId: result && result.sessionId ? result.sessionId : null,
			paidAt: result && result.executedAt ? result.executedAt : null
		},
		items: stockItems(state)
	};
}

function stockManagedPaymentAction(state, paymentRequest) {
	const config = SHOP_CONFIG.stockManagement || {};
	const provider = config.provider || 'none';
	const paymentConfig = SHOP_CONFIG.orderPayment || {};
	const paymentWebhookUrl = paymentConfig.webhookUrl || '';
	if (!paymentWebhookUrl && (provider === 'none' || provider !== 'api' || !config.apiUrl)) {
		return {
			type: 'payment',
			request: paymentRequest
		};
	}

	return {
		type: 'stockCheckedPayment',
		check: {
			url: paymentWebhookUrl || config.apiUrl,
			body: paymentWebhookUrl
				? orderPreparePayload(state, {
					request: paymentRequest,
					sessionId: null,
					executedAt: null
				})
				: stockPayload(state, 'shop.stock.validate')
		},
		storageKey: STATE_KEY,
		cart: state.cart,
		request: paymentRequest
	};
}

async function sendStockAdjustment(hostApi, state, result) {
	const config = SHOP_CONFIG.stockManagement || {};
	const provider = config.provider || 'none';
	if (provider === 'none') return { ok: true, adjusted: false, reason: 'Stock management disabled.' };
	if (provider !== 'api') return { ok: true, adjusted: false, reason: `Unsupported stock provider: ${provider}` };
	if (!config.apiUrl) return { ok: true, adjusted: false, reason: 'Stock API endpoint is not configured.' };

	const response = await hostApi.network.postJson({
		url: config.apiUrl,
		body: stockPayload(state, 'shop.stock.decrement', result)
	});
	if (!response.ok) {
		throw new Error(`Stock API failed (${response.status}).`);
	}
	return { ok: true, adjusted: true, provider: 'api' };
}


// src/email.ts
// @ts-nocheck
function escapeHtml(value) {
	return String(value ?? '')
		.replace(/&/g, '&amp;')
		.replace(/</g, '&lt;')
		.replace(/>/g, '&gt;')
		.replace(/"/g, '&quot;')
		.replace(/'/g, '&#39;');
}

function orderEmailItems(state) {
	return cartItems(state).map((item) => ({
		id: item.product.id,
		skuid: item.product.skuid || '',
		name: item.product.name,
		quantity: item.quantity,
		unitPrice: formatMoney(item.product.price, state.settings.currency),
		lineTotal: formatMoney(item.product.price * item.quantity, state.settings.currency),
		cid: item.product.cid
	}));
}

function orderEmailSubject(state, result) {
	const prefix = SHOP_CONFIG.orderEmail.subjectPrefix || 'New shop order';
	const reference = result.request && result.request.reference ? result.request.reference : orderReference(state);
	return `${prefix}: ${reference}`;
}

function shopAdminEmail(state) {
	return (state.settings && state.settings.adminEmail) || SHOP_CONFIG.orderEmail.adminEmail || '';
}

function orderFulfillmentMode() {
	const fulfillment = SHOP_CONFIG.orderFulfillment || {};
	const mode = String(fulfillment.mode || 'email').trim().toLowerCase();
	return ['email', 'webhook', 'both', 'storage', 'none'].includes(mode) ? mode : 'email';
}

function orderCollectionMessage(state) {
	const config = SHOP_CONFIG.orderEmail || {};
	const fulfillment = SHOP_CONFIG.orderFulfillment || {};
	const mode = orderFulfillmentMode();
	if (mode === 'none') return 'No order collection is configured, please contact admin.';
	const webhookUrl = fulfillment.webhookUrl || config.webhookUrl || '';
	const hasEmail = Boolean(shopAdminEmail(state));
	const hasWebhook = Boolean(webhookUrl);
	const configured =
		(mode === 'email' && hasEmail && hasWebhook) ||
		(mode === 'webhook' && hasWebhook) ||
		(mode === 'both' && hasEmail && hasWebhook) ||
		(mode === 'storage' && hasWebhook);
	return configured ? '' : 'No order collection is configured, please contact admin.';
}

function customerEmailSubject(state, result) {
	const reference = result.request && result.request.reference ? result.request.reference : orderReference(state);
	return `Your ${SHOP_CONFIG.name} order: ${reference}`;
}

function orderEmailText(state, result) {
	const reference = result.request && result.request.reference ? result.request.reference : orderReference(state);
	const delivery = state.delivery || {};
	const items = orderEmailItems(state);
	const deliveryFee = deliveryFeeAmount(state);
	const paidAt = result.executedAt || 'n/a';
	return [
		`A new ${SHOP_CONFIG.name} order was paid.`,
		'',
		`Reference: ${reference}`,
		`Payment session: ${result.sessionId || 'n/a'}`,
		`Paid at: ${paidAt}`,
		`Subtotal: ${formatMoney(cartSubtotal(state), state.settings.currency)}`,
		`Delivery fee: ${formatMoney(deliveryFee, state.settings.currency)}`,
		`Total: ${formatMoney(cartTotal(state), state.settings.currency)}`,
		'',
		'Items:',
		...items.map((item) => `- ${item.name} × ${item.quantity}: ${item.lineTotal}${item.skuid ? ` [${item.skuid}]` : ''} (${item.cid})`),
		'',
		'Delivery:',
		`Name: ${delivery.name || 'n/a'}`,
		`Email: ${delivery.email || 'n/a'}`,
		`Phone: ${delivery.phone || 'n/a'}`,
		`Address: ${delivery.address || 'n/a'}`,
		`Address 2: ${delivery.address2 || 'n/a'}`,
		`City: ${delivery.city || 'n/a'}`,
		`State: ${delivery.state || 'n/a'}`,
		`ZIP: ${delivery.zip || 'n/a'}`,
		`Country: ${delivery.country || 'n/a'}`,
		`Notes: ${delivery.notes || 'n/a'}`,
		'',
		`User CoreID: ${state.coreId || 'n/a'}`
	].join('\n');
}

function orderEmailHtml(state, result) {
	const reference = result.request && result.request.reference ? result.request.reference : orderReference(state);
	const delivery = state.delivery || {};
	const items = orderEmailItems(state);
	const deliveryFee = deliveryFeeAmount(state);
	const paidAt = result.executedAt || 'n/a';
	return [
		`<h1>New paid ${escapeHtml(SHOP_CONFIG.name)} order</h1>`,
		'<h2>Payment</h2>',
		'<ul>',
		`<li><strong>Reference:</strong> ${escapeHtml(reference)}</li>`,
		`<li><strong>Payment session:</strong> ${escapeHtml(result.sessionId || 'n/a')}</li>`,
		`<li><strong>Paid at:</strong> ${escapeHtml(paidAt)}</li>`,
		`<li><strong>Subtotal:</strong> ${escapeHtml(formatMoney(cartSubtotal(state), state.settings.currency))}</li>`,
		`<li><strong>Delivery fee:</strong> ${escapeHtml(formatMoney(deliveryFee, state.settings.currency))}</li>`,
		`<li><strong>Total:</strong> ${escapeHtml(formatMoney(cartTotal(state), state.settings.currency))}</li>`,
		'</ul>',
		'<h2>Items</h2>',
		'<ul>',
		...items.map((item) => `<li><strong>${escapeHtml(item.name)}</strong> × ${escapeHtml(item.quantity)} — ${escapeHtml(item.lineTotal)}${item.skuid ? ` <small>${escapeHtml(item.skuid)}</small>` : ''}<br><small>${escapeHtml(item.cid)}</small></li>`),
		'</ul>',
		'<h2>Delivery</h2>',
		'<ul>',
		`<li><strong>Name:</strong> ${escapeHtml(delivery.name || 'n/a')}</li>`,
		`<li><strong>Email:</strong> ${escapeHtml(delivery.email || 'n/a')}</li>`,
		`<li><strong>Phone:</strong> ${escapeHtml(delivery.phone || 'n/a')}</li>`,
		`<li><strong>Address:</strong> ${escapeHtml(delivery.address || 'n/a')}</li>`,
		`<li><strong>Address 2:</strong> ${escapeHtml(delivery.address2 || 'n/a')}</li>`,
		`<li><strong>City:</strong> ${escapeHtml(delivery.city || 'n/a')}</li>`,
		`<li><strong>State:</strong> ${escapeHtml(delivery.state || 'n/a')}</li>`,
		`<li><strong>ZIP:</strong> ${escapeHtml(delivery.zip || 'n/a')}</li>`,
		`<li><strong>Country:</strong> ${escapeHtml(delivery.country || 'n/a')}</li>`,
		`<li><strong>Notes:</strong> ${escapeHtml(delivery.notes || 'n/a')}</li>`,
		'</ul>',
		`<p><strong>User CoreID:</strong> ${escapeHtml(state.coreId || 'n/a')}</p>`
	].join('');
}

function mailtoOrderUrl(state, result) {
	const email = SHOP_CONFIG.orderEmail.adminEmail || '';
	const subject = orderEmailSubject(state, result);
	const body = orderEmailText(state, result);
	return `mailto:${encodeURIComponent(email)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(body)}`;
}

function orderWebhookPayload(state, result) {
	const reference = result.request && result.request.reference ? result.request.reference : orderReference(state);
	const fulfillment = SHOP_CONFIG.orderFulfillment || {};
	const adminEmail = shopAdminEmail(state);
	const emails = [
		...(adminEmail
			? [{
				type: 'admin',
				to: adminEmail,
				replyTo: state.delivery && state.delivery.email ? state.delivery.email : null,
				subject: orderEmailSubject(state, result),
				text: orderEmailText(state, result),
				html: orderEmailHtml(state, result)
			}]
			: []),
		...(SHOP_CONFIG.orderEmail.sendCustomerReceipt && state.delivery && state.delivery.email
			? [{
				type: 'customer',
				to: state.delivery.email,
				replyTo: adminEmail || null,
				subject: customerEmailSubject(state, result),
				text: orderEmailText(state, result),
				html: orderEmailHtml(state, result)
			}]
			: [])
	];
	return {
		type: 'shop.order.paid',
		fulfillment: {
			mode: fulfillment.mode || 'email'
		},
		shop: {
			name: SHOP_CONFIG.name,
			adminEmail: adminEmail || null
		},
		payment: {
			reference,
			sessionId: result.sessionId || null,
			paidAt: result.executedAt || null,
			subtotal: cartSubtotal(state),
			deliveryFee: deliveryFeeAmount(state),
			total: cartTotal(state),
			currency: state.settings.currency
		},
		customer: {
			coreId: state.coreId || null,
			name: state.delivery && state.delivery.name ? state.delivery.name : null,
			email: state.delivery && state.delivery.email ? state.delivery.email : null,
			replyTo: state.delivery && state.delivery.email ? state.delivery.email : null
		},
		delivery: state.delivery,
		items: orderEmailItems(state),
		emails,
		email: {
			to: adminEmail,
			replyTo: state.delivery && state.delivery.email ? state.delivery.email : null,
			subject: orderEmailSubject(state, result),
			text: orderEmailText(state, result),
			html: orderEmailHtml(state, result)
		}
	};
}

function orderPreparePayload(state, result) {
	return {
		...orderWebhookPayload(state, result),
		type: 'shop.order.prepare'
	};
}

async function sendAdminOrderEmail(hostApi, state, result) {
	const config = SHOP_CONFIG.orderEmail || {};
	const fulfillment = SHOP_CONFIG.orderFulfillment || {};
	const provider = config.provider || (fulfillment.webhookUrl ? 'webhook' : 'none');
	const mode = orderFulfillmentMode();
	const adminEmail = shopAdminEmail(state);
	if (provider === 'none' || mode === 'none') return { ok: true, sent: false, reason: 'Order fulfillment disabled.' };
	if (mode === 'email' && !adminEmail) return { ok: true, sent: false, reason: 'Admin email disabled.' };

	if (provider === 'mailto') {
		await hostApi.ui.navigate(mailtoOrderUrl(state, result));
		return { ok: true, sent: true, provider: 'mailto' };
	}

	if (provider !== 'webhook') return { ok: true, sent: false, reason: `Unsupported email provider: ${provider}` };
	const webhookUrl = fulfillment.webhookUrl || config.webhookUrl;
	if (!webhookUrl) return { ok: true, sent: false, reason: 'Order fulfillment webhook is not configured.' };

	const response = await hostApi.network.postJson({
		url: webhookUrl,
		body: orderWebhookPayload(state, result)
	});
	if (!response.ok) {
		throw new Error(`Order fulfillment webhook failed (${response.status}).`);
	}
	return { ok: true, sent: mode === 'email' || mode === 'both', provider: 'webhook', mode };
}


// src/plugin.ts
// @ts-nocheck
module.exports = {
	default: {
		setup(hostApi) {
			this.hostApi = hostApi;
			const initialView = readInitialPluginView();
			if (initialView) {
				saveState(hostApi, {
					...getState(hostApi),
					view: initialView
				});
			}
			this.unsubscribe = hostApi.events.onPaymentExecuted((result) => {
				const state = getState(hostApi);
				if (result.status === 'executed') {
					const paidAt = result.executedAt || '';
					const lastOrder = {
						status: 'paid',
						total: cartTotal(state),
						subtotal: cartSubtotal(state),
						deliveryFee: deliveryFeeAmount(state),
						currency: state.settings.currency,
						reference: result.request && result.request.reference ? result.request.reference : orderReference(state),
						sessionId: result.sessionId,
						paidAt,
						delivery: deliverySummary(state.delivery)
					};
					saveState(hostApi, {
						...state,
						view: 'success',
						cart: {},
						checkoutStatus: 'paid',
						lastOrder,
						savedDelivery: state.saveDelivery && hasDeliveryAddress(state.delivery) ? state.delivery : state.savedDelivery,
						savedDeliveries: state.saveDelivery
							? upsertSavedDeliveryProfile(state.savedDeliveries, state.delivery)
							: state.savedDeliveries,
						selectedDeliveryProfileId: state.saveDelivery && hasDeliveryAddress(state.delivery)
							? deliveryProfileId(state.delivery)
							: state.selectedDeliveryProfileId
					});
					hostApi.ui.notify('Order paid. The merchant can fulfill it using the payment reference.', 'success');
					if (SHOP_CONFIG.orderPayment && SHOP_CONFIG.orderPayment.webhookUrl) {
						hostApi.ui.toast('Order fulfillment will continue after payment verification.', 'success');
					} else {
						sendAdminOrderEmail(hostApi, state, result)
							.then((emailResult) => {
								if (emailResult && emailResult.sent) {
									hostApi.ui.toast('Order email sent to shop admin.', 'success');
								}
							})
							.catch((error) => {
								const message = error && error.message ? error.message : 'Unable to send order fulfillment.';
								hostApi.ui.notify(message, 'error');
							});
						sendStockAdjustment(hostApi, state, result)
							.then((stockResult) => {
								if (stockResult && stockResult.adjusted) {
									hostApi.ui.toast('Stock updated.', 'success');
								}
							})
							.catch((error) => {
								const message = error && error.message ? error.message : 'Unable to update stock.';
								hostApi.ui.notify(message, 'warning');
							});
					}
				} else if (result.status === 'opened') {
					saveState(hostApi, {
						...state,
						checkoutStatus: 'payment_opened'
					});
				} else if (result.status === 'failed' || result.status === 'cancelled' || result.status === 'expired') {
					saveState(hostApi, {
						...state,
						view: 'failed',
						checkoutStatus: result.status
					});
				}
			});
			hostApi.user.getProfile({ coreId: true, countryCode: true })
				.then((profile) => {
					if (!profile) return;
					const state = getState(hostApi);
					const country = countryCodeFromValue(state.delivery.country) || countryCodeFromValue(profile.countryCode);
					saveState(hostApi, {
						...state,
						coreId: state.coreId || profile.coreId,
						countryCode: state.countryCode || profile.countryCode || '',
						delivery: {
							...state.delivery,
							country
						}
					});
				})
				.catch(() => {});
			hostApi.user.getCoreId()
				.then((coreId) => {
					if (!coreId) return;
					const state = getState(hostApi);
					saveState(hostApi, {
						...state,
						coreId
					});
				})
				.catch(() => {});
		},

		render() {
			const api = this.hostApi || hostApi;
			const state = getState(api);
			maybeLoadCatalog(api, state);
			maybeRequestCheckoutEmail(api, state);
			return {
				title: SHOP_CONFIG.name,
				nodes: [
					renderView(state)
				]
			};
		},

		dispose() {
			if (typeof this.unsubscribe === 'function') this.unsubscribe();
		}
	}
};

function maybeRequestCheckoutEmail(api, state) {
	if (state.view !== 'checkout') return;
	if (state.userEmail || state.delivery.email || state.emailRequestStatus !== 'idle') return;
	saveState(api, {
		...state,
		emailRequestStatus: 'requested'
	});
	api.user.getProfile({ email: true })
		.then((profile) => {
			const nextState = getState(api);
			const email = profile && profile.email ? profile.email : '';
			saveState(api, {
				...nextState,
				userEmail: nextState.userEmail || email,
				emailRequestStatus: 'resolved',
				delivery: {
					...nextState.delivery,
					email: nextState.delivery.email || email
				}
			});
		})
		.catch(() => {
			const nextState = getState(api);
			saveState(api, {
				...nextState,
				emailRequestStatus: 'resolved'
			});
		});
}

function readInitialPluginView() {
	const context = typeof pluginContext === 'object' && pluginContext ? pluginContext : null;
	const view = context && typeof context.initialView === 'string'
		? context.initialView.trim().toLowerCase()
		: '';
	return ['products', 'product', 'cart', 'checkout', 'orders', 'success', 'failed', 'contact'].includes(view) ? view : null;
}

